import { readFileSync } from 'fs';
import { dirname, join, relative, resolve, sep } from 'path';
import { transform } from 'lightningcss';
const cwd = process.cwd();
async function bundleFile(filePath) {
    const dir = dirname(filePath);
    const source = readFileSync(filePath, 'utf8');
    const { code, dependencies } = transform({
        filename: filePath,
        code: Buffer.from(source),
        analyzeDependencies: { preserveImports: true },
        minify: false
    });
    const raw = code.toString();
    let result = '';
    if (dependencies) {
        for (const dep of dependencies) {
            if (dep.type !== 'import')
                continue;
            const resolvedPath = resolve(dir, dep.url);
            let bundledDep = await bundleFile(resolvedPath);
            if (dep.supports)
                bundledDep = `@supports ${dep.supports} {\n${indent(bundledDep)}\n}\n`;
            if (dep.media)
                bundledDep = `@media ${dep.media} {\n${indent(bundledDep)}\n}\n`;
            result += `${bundledDep}\n`;
        }
    }
    const ownRules = raw.replace(/@import "[^"]+"[^;]*;\n?/g, '').trim();
    if (ownRules) {
        const relativeSelf = relative(cwd, filePath).split(sep).join('/');
        result += `/* --- ${relativeSelf} --- */\n${ownRules}\n`;
    }
    return result;
}
function indent(css) {
    return css
        .split('\n')
        .map((line) => (line ? `\t${line}` : line))
        .join('\n')
        .trimEnd();
}
export const bundle = (entry) => bundleFile(join(cwd, entry));
